### Version

v18.18.0

### Platform

x64 window

### Subsystem

_No response_

### What steps will reproduce the bug?

```

let sleep_cpu_bound = function (time) {
    return new Promise((resolve, reject) => {
        var stop = new Date().getTime();
        while (new Date().getTime() < stop + time) {
            ;
        }
   
        return resolve(true)
    });
}
 
async function call_api_1() {
    try {
        console.log('entering the fetchData function');
 
        await sleep_cpu_bound(1000);
  
 
        const response_1 = await fetch('https://jsonplaceholder.typicode.com/posts/1');
 
        if (!response_1.ok) {
            throw new Error(`Error when calling API_1: ${response_1.status}`);
        }
 
        const data = await response_1.json();
        console.log('API_1 is coming');
 
        return data;
    } catch (error) {
        console.error('Error when calling API:', error);
        throw error;
    }
}
 
async function call_api_2() {
    try {
        console.log('entering the fetchSlowData function');
 
        const response_2 = await fetch('https://jsonplaceholder.typicode.com/comments/1');
        if (!response_2.ok) {
            throw new Error(`Error when calling API_2: ${response_2.status}`);
        }
 
        const data = await response_2.json();
        console.log('API_2 is coming');
        return data;
    } catch (error) {
        console.error('Error when calling slow API:', error);
        throw error;
    }
}
 
function checkings_1() {
    console.log('checking_1')
}
 
function checkings_2() {
    console.log('checking_2')
}
 
function checkings_3() {
    console.log('checking_3')
}
 
async function main() {
    const promise2 = call_api_2();
    console.log('promise_2', promise2);
    const promise1 = call_api_1();
    console.log('promise_1', promise1);
 
    checkings_1();
    checkings_2();
 
    const [data2, data1] = await Promise.all([promise2, promise1]); // Wait for both promises to complete
 
    checkings_3();
    console.log('Ending');
}
 
main()
```


### How often does it reproduce? Is there a required condition?

Occasionally, and inconsistently across executions.

### What is the expected behavior? Why is that the expected behavior?
entering the fetchSlowData function
promise_2 Promise { <pending> }
entering the fetchData function
promise_1 Promise { <pending> }
checking_1
checking_2
API_2 is coming
API_1 is coming
checking_3
Ending

### What do you see instead?

entering the fetchSlowData function
promise_2 Promise { <pending> }
entering the fetchData function
promise_1 Promise { <pending> }
checking_1
checking_2
API_1 is coming
API_2 is coming
checking_3
Ending


### Additional information

hi You, in this piece of code, I intentionally want to notify 'API_2 is coming' first, so I placed the 'sleep()' function inside the 'call_api_1' function. However, when I run it on Node v18, I receive a strange result where sometimes 'API_2 is coming' appears first, and other times 'API_1 is coming' appears first on the screen. But when I check it in the Chrome browser, I consistently get the result 'API_2 is coming' first. I've tried to explain it, but I don't know the reason why. It seems to be a Node.js issue.

thank you!
